package cn.zhuatech.ppm.controller; import cn.zhuatech.ppm.common.ApiResponse; import cn.zhuatech.ppm.dto.PpmDto.*; import cn.zhuatech.ppm.service.PpmService; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/admin") @PreAuthorize("hasAnyRole('PPM_DIRECTOR','QUALITY','ADMIN')") public class PortfolioAdminController {private final PpmService service;public PortfolioAdminController(PpmService service){this.service=service;}@GetMapping("/dashboard") public ApiResponse<Dashboard> dashboard(){return ApiResponse.ok(service.adminDashboard());}@GetMapping("/work-orders") public ApiResponse<List<InitiativeReviewView>> orders(){return ApiResponse.ok(service.initiativeReviews());}}
